    23	
    24	    static Javalin create(Store store, CarrierGateway carrier, Clock clock) {
    25	        PricingService pricing = new PricingService(ShippingMethods.standard(carrier), Coupons.standard(),
    26	                PaymentMethods.standard());
    27	        Api api = new Api(new OrderService(store, pricing, clock), store);
    28	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    29	
    30	        app.post("/checkout/summary", ctx -> reply(ctx, 200, () -> orders(api).summary(parse(ctx))));
    31	        app.post("/orders", ctx -> reply(ctx, 201, () -> view(orders(api).register(parse(ctx)))));
    32	        app.get("/orders/{id}", ctx -> reply(ctx, 200, () -> view(orders(api).get(ctx.pathParam("id")))));
    33	        app.post("/orders/{id}/payment", ctx -> {
    34	            JsonNode body = Json.tree(ctx.body());
    35	            reply(ctx, 200, () -> view(orders(api).pay(ctx.pathParam("id"), text(body, "transactionId"),
    36	                    text(body, "paidAt"))));
    37	        });
    38	        app.post("/orders/{id}/shipment", ctx -> {
    39	            JsonNode body = Json.tree(ctx.body());
    40	            reply(ctx, 200, () -> view(orders(api).ship(ctx.pathParam("id"), text(body, "trackingCode"))));
    41	        });
    42	        app.post("/orders/{id}/delivery", ctx -> reply(ctx, 200, () -> view(orders(api).deliver(ctx.pathParam("id")))));
    43	        app.post("/orders/{id}/cancellation", ctx -> reply(ctx, 200, () -> view(orders(api).cancel(ctx.pathParam("id")))));
    44	
    45	        app.get("/products/{sku}", ctx -> reply(ctx, 200, () -> api.store.transaction(tx ->
    46	                tx.findProduct(ctx.pathParam("sku")).map(Api::view)
    47	                        .orElseThrow(() -> ApiException.notFound("PRODUCT_NOT_FOUND")))));
    48	        app.get("/customers/{cpf}", ctx -> reply(ctx, 200, () -> api.store.transaction(tx ->
    49	                tx.findCustomer(ctx.pathParam("cpf")).map(c -> {
    50	                    Map<String, Object> m = new LinkedHashMap<>();
    51	                    m.put("cpf", c.cpf());
    52	                    m.put("creditBalance", c.creditBalance());
    53	                    return m;
    54	                }).orElseThrow(() -> ApiException.notFound("CUSTOMER_NOT_FOUND")))));
    55	        app.get("/customers/{cpf}/notifications", ctx -> reply(ctx, 200, () -> api.store.transaction(tx -> {
    56	            String cpf = ctx.pathParam("cpf");
    57	            tx.findCustomer(cpf).orElseThrow(() -> ApiException.notFound("CUSTOMER_NOT_FOUND"));
    58	            return tx.notifications(cpf).stream().map(Api::view).toList();
    59	        })));
    60	        app.post("/notifications/{id}/read", ctx -> reply(ctx, 200, () -> api.store.transaction(tx -> {
    61	            long id;
    62	            try {
    63	                id = Long.parseLong(ctx.pathParam("id"));
    64	            } catch (NumberFormatException e) {
    65	                throw ApiException.notFound("NOTIFICATION_NOT_FOUND");
    66	            }
    67	            return tx.markRead(id).map(Api::view).orElseThrow(() -> ApiException.notFound("NOTIFICATION_NOT_FOUND"));
    68	        })));
    69	
    70	        app.exception(Exception.class, (e, ctx) -> {
    71	            e.printStackTrace();
    72	            send(ctx, 500, Map.of("error", "INTERNAL_ERROR"));
    73	        });
    74	        return app;
    75	    }
    76	
    77	    private static OrderService orders(Api api) {
    78	        return api.orders;
    79	    }
    80	
    81	    private static CheckoutRequest parse(Context ctx) {
    82	        return CheckoutRequest.parse(Json.tree(ctx.body()));
    83	    }
    84	
    85	    private static String text(JsonNode body, String field) {
    86	        if (body == null || !body.isObject()) return null;
    87	        JsonNode n = body.get(field);
    88	        return n != null && n.isTextual() ? n.asText() : null;
    89	    }
    90	
    91	    private static void reply(Context ctx, int okStatus, Supplier<Object> work) {
    92	        try {
    93	            send(ctx, okStatus, work.get());
    94	        } catch (ApiException e) {
    95	            send(ctx, e.status(), Map.of("error", e.code()));
    96	        }
    97	    }
    98	
    99	    private static void send(Context ctx, int status, Object body) {
   100	        ctx.status(status).contentType("application/json").result(Json.write(body));
   101	    }
   102	
   103	    private static String iso(java.time.Instant instant) {
   104	        return DateTimeFormatter.ISO_INSTANT.format(instant.truncatedTo(ChronoUnit.SECONDS));
   105	    }
   106	
   107	    static Map<String, Object> view(Order o) {
   108	        Map<String, Object> m = new LinkedHashMap<>();
   109	        m.put("id", o.id());
   110	        m.put("status", o.status());
   111	        m.put("createdAt", iso(o.createdAt()));
   112	        m.put("summary", o.summary());
   113	        m.put("items", o.items());
