     6	import com.fasterxml.jackson.databind.SerializationFeature;
     7	import com.fasterxml.jackson.core.JsonGenerator;
     8	
     9	final class Json {
    10	    static final ObjectMapper MAPPER = new ObjectMapper()
    11	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
    12	            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
    13	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
    14	
    15	    private Json() {}
    16	
    17	    static String write(Object value) {
    18	        try {
    19	            return MAPPER.writeValueAsString(value);
    20	        } catch (Exception e) {
    21	            throw new IllegalStateException(e);
    22	        }
    23	    }
    24	
    25	    static <T> T read(String text, Class<T> type) {
    26	        try {
    27	            return MAPPER.readValue(text, type);
    28	        } catch (Exception e) {
    29	            throw new IllegalStateException(e);
    30	        }
    31	    }
    32	
    33	    /** Lê o corpo; devolve null se for vazio ou não for JSON. */
    34	    static JsonNode tree(String text) {
    35	        try {
    36	            return text == null || text.isBlank() ? null : MAPPER.readTree(text);
    37	        } catch (Exception e) {
    38	            return null;
    39	        }
    40	    }
