    10	
    11	/** Uma forma de pagamento: cada nova forma é uma nova implementação registrada em {@link PaymentMethods}. */
    12	interface PaymentMethod {
    13	    String code();
    14	
    15	    boolean acceptsInstallments(int installments);
    16	
    17	    boolean availableFor(BigDecimal orderTotal);
    18	
    19	    PaymentOutcome settle(BigDecimal orderTotal, int installments, boolean couponUsed);
    20	}
    21	
    22	final class PaymentMethods {
    23	    private final Map<String, PaymentMethod> byCode = new LinkedHashMap<>();
    24	
    25	    PaymentMethods(PaymentMethod... methods) {
    26	        for (PaymentMethod m : methods) byCode.put(m.code(), m);
    27	    }
    28	
    29	    static PaymentMethods standard() {
    30	        return new PaymentMethods(new Pix(), new CreditCard(), new BankSlip());
    31	    }
    32	
    33	    PaymentMethod get(String code) {
    34	        return code == null ? null : byCode.get(code);
    35	    }
    36	
    37	    static final class Pix implements PaymentMethod {
    38	        public String code() { return "PIX"; }
    39	
    40	        public boolean acceptsInstallments(int n) { return n == 1; }
    41	
    42	        public boolean availableFor(BigDecimal total) { return true; }
    43	
    44	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
    45	            BigDecimal result = couponUsed ? total : total.subtract(Money.percent(total, "0.05"));
    46	            return new PaymentOutcome(result, result);
    47	        }
    48	    }
    49	
    50	    static final class BankSlip implements PaymentMethod {
    51	        private static final BigDecimal FEE = new BigDecimal("3.49");
    52	        private static final BigDecimal MAX_TOTAL = new BigDecimal("1000.00");
    53	
    54	        public String code() { return "BANK_SLIP"; }
    55	
    56	        public boolean acceptsInstallments(int n) { return n == 1; }
    57	
    58	        public boolean availableFor(BigDecimal total) { return total.compareTo(MAX_TOTAL) <= 0; }
    59	
    60	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
    61	            BigDecimal result = total.add(FEE);
    62	            return new PaymentOutcome(result, result);
    63	        }
    64	    }
    65	
    66	    static final class CreditCard implements PaymentMethod {
    67	        private static final int MAX_INTEREST_FREE = 3;
    68	        private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
    69	        private static final MathContext MC = new MathContext(40);
    70	
    71	        public String code() { return "CREDIT_CARD"; }
    72	
    73	        public boolean acceptsInstallments(int n) { return n >= 1 && n <= 12; }
    74	
    75	        public boolean availableFor(BigDecimal total) { return true; }
    76	
    77	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
    78	            BigDecimal count = BigDecimal.valueOf(n);
    79	            if (n <= MAX_INTEREST_FREE) {
    80	                return new PaymentOutcome(total, total.divide(count, 2, RoundingMode.HALF_EVEN));
    81	            }
    82	            // Tabela Price: parcela = total * i / (1 - (1 + i)^-n)
    83	            BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(n, MC);
    84	            BigDecimal denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, MC), MC);
    85	            BigDecimal installment = Money.round(total.multiply(MONTHLY_RATE).divide(denominator, MC));
    86	            return new PaymentOutcome(installment.multiply(count), installment);
    87	        }
    88	    }
    89	}
