    24	        this.baseUrl = baseUrl == null ? null : baseUrl.replaceAll("/+$", "");
    25	    }
    26	
    27	    @Override
    28	    public Optional<CarrierQuote> quote(String zipCode, long weightGrams, String service) {
    29	        if (baseUrl == null || baseUrl.isBlank()) throw new CarrierDownException("TRANSLOG_URL not set", null);
    30	        CompletableFuture<HttpResponse<String>> future = null;
    31	        try {
    32	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams + "&service=" + service);
    33	            HttpRequest request = HttpRequest.newBuilder(uri).GET().build();
    34	            future = client.sendAsync(request, HttpResponse.BodyHandlers.ofString());
    35	            HttpResponse<String> response = future.get(TIMEOUT_MS, TimeUnit.MILLISECONDS);
    36	            if (response.statusCode() != 200) throw new CarrierDownException("status " + response.statusCode(), null);
    37	            return parse(response.body());
    38	        } catch (CarrierDownException e) {
    39	            throw e;
    40	        } catch (InterruptedException e) {
    41	            Thread.currentThread().interrupt();
    42	            throw new CarrierDownException("interrupted", e);
    43	        } catch (Exception e) {
    44	            throw new CarrierDownException("TransLog failure", e);
    45	        } finally {
    46	            if (future != null) future.cancel(true);
    47	        }
    48	    }
    49	
    50	    private static Optional<CarrierQuote> parse(String body) throws Exception {
    51	        JsonNode json = MAPPER.readTree(body);
    52	        if (json == null || !json.isObject()) throw new CarrierDownException("unexpected body", null);
    53	        JsonNode error = json.get("error");
    54	        if (error != null) {
    55	            if (error.isTextual() && error.asText().equals("ZIP_NOT_SERVED")) return Optional.empty();
    56	            throw new CarrierDownException("carrier error", null);
    57	        }
    58	        JsonNode price = json.get("price_cents");
    59	        JsonNode eta = json.get("eta_hours");
    60	        if (price == null || eta == null || !price.isIntegralNumber() || !eta.isIntegralNumber()
    61	                || !price.canConvertToLong() || !eta.canConvertToInt() || price.asLong() < 0 || eta.asInt() < 0) {
    62	            throw new CarrierDownException("unexpected body", null);
    63	        }
    64	        return Optional.of(new CarrierQuote(BigDecimal.valueOf(price.asLong(), 2), eta.asInt()));
    65	    }
    66	}
